#!/usr/bin/env python3
"""Reconcile templates/flagged.tpl after merging the parallel session's work.

The parallel session (4830ab32) had already renumbered the duplicated F-54 row to F-58
and published F-59 plus F-BFC-01/F-BFC-03. This script keeps every one of those rows and
their wording, corrects the rows that no longer reproduce, and appends the findings of
session-9bee7c49 under IDs that do not collide (F-60 upwards).
"""
import io
import re

P = 'templates/flagged.tpl'
src = io.open(P, encoding='utf8').read()
lines = src.split('\n')


def row_start(fid):
    for i, l in enumerate(lines):
        if f'id="{fid}"' in l:
            return i
    raise SystemExit('row %s not found' % fid)


def get_row(fid):
    return lines[row_start(fid)]


def set_row(fid, text):
    lines[row_start(fid)] = text


def append_to_row(fid, html):
    i = row_start(fid)
    lines[i] = lines[i].replace('</tr>', html + '</tr>')


# ---------------------------------------------------------------- F-44
set_row('F-44', '''        <tr><td><span id="F-44"></span>F-44</td><td>CI failure (repair observed, then hardened 2026-11-21)</td><td>Scheduled refresh and alert runs on 2026-11-21 fetched and validated data but failed at their commit steps. Both previous commit scripts omitted a closing <code>fi</code>; <code>bash -n</code> rejects them, and a bash syntax error exits with code <strong>2</strong> — which is exactly the job annotation those runs carried ("Process completed with exit code 2"). The raw failed-run logs could not be retrieved here, so their exact error was unverified at the time. After the repair, push-triggered <code>main</code> runs succeeded, including both commit steps, and produced new engine and snapshot commits. <strong>Hardening (session 9bee7c49, 2026-11-21):</strong> the publish step was replaced entirely, so it can no longer depend on a hand-written multi-branch shell script. <code>scripts/publish-data.sh</code> publishes by <em>moving</em> HEAD onto the fetched remote tip (<code>git reset --mixed FETCH_HEAD</code>), staging only the pathspecs it is given, committing on top of that tip and fast-forwarding — it never merges, so there is nothing to conflict, and it can never revert a file it did not generate. The behaviour is proved by <code>tools/test_publish.sh</code>, which runs in CI. A <code>bash -n</code> check over every shell block in every workflow (<code>scripts/check-data-workflow-shells.mjs</code>) now guards against the syntax error recurring; it was extended from the two data writers to all eight workflow files. Scheduled execution and continued freshness are not guaranteed.</td><td>CI, data freshness</td><td><a href="https://github.com/kanlerxz87-cyber/KalshiDash1/actions/runs/44860334644" target="_blank" rel="noopener">Failed scheduled refresh &rarr;</a> · <a href="https://github.com/kanlerxz87-cyber/KalshiDash1/actions/runs/44858392056" target="_blank" rel="noopener">Failed scheduled alert &rarr;</a> · <a href="https://github.com/kanlerxz87-cyber/KalshiDash1/blob/main/scripts/publish-data.sh" target="_blank" rel="noopener">scripts/publish-data.sh &rarr;</a> · <a href="https://github.com/kanlerxz87-cyber/KalshiDash1/blob/main/tools/test_publish.sh" target="_blank" rel="noopener">tools/test_publish.sh &rarr;</a> · <a href="https://github.com/kanlerxz87-cyber/KalshiDash1/blob/main/scripts/check-data-workflow-shells.mjs" target="_blank" rel="noopener">the shell-syntax guard &rarr;</a></td><td><span class="badge warn">Needs main-branch validation</span></td></tr>''')

